cat > policies.ts <<'EOF'
// Mandatory guardrails for prod stacks (framework layer 5; they compensate OD8, where the stack's
// owners, not the L3 owner team, approve IAM and stateful changes inside domain files).
// Phase 2. Run by `pulumi up --policy-pack` in deploy-prod.yml; "a violation of a mandatory
// policy stops the deployment" (R4.2.2). Exported separately from index.ts so that tests can
// call the checks without the Pulumi engine.
import * as aws from "@pulumi/aws";
import { ResourceValidationPolicy, validateResourceOfType } from "@pulumi/policy";

type Statement = { Effect?: string; Action?: string | string[]; NotAction?: string | string[] };

function statementsOf(policy: unknown): Statement[] {
    if (policy === undefined || policy === null) return [];
    const doc = typeof policy === "string" ? JSON.parse(policy) : policy;
    const st = (doc as { Statement?: Statement | Statement[] }).Statement ?? [];
    return Array.isArray(st) ? st : [st];
}

function wildcardActions(policy: unknown): string[] {
    const found: string[] = [];
    for (const st of statementsOf(policy)) {
        if (st.Effect !== "Allow") continue;
        if (st.NotAction !== undefined) found.push("NotAction");
        const actions = st.Action === undefined ? [] : Array.isArray(st.Action) ? st.Action : [st.Action];
        for (const a of actions) {
            if (a === "*" || /^[a-z0-9-]+:\*$/i.test(a)) found.push(a);
        }
    }
    return found;
}

function report(actions: string[], reportViolation: (m: string) => void) {
    if (actions.length > 0) {
        reportViolation(`IAM Allow with a wildcard action (${actions.join(", ")}); name the actions.`);
    }
}

export const policies: ResourceValidationPolicy[] = [
    {
        name: "iam-no-wildcard-actions",
        description: "IAM policies may not allow `*`, `<service>:*` or use NotAction with Allow.",
        enforcementLevel: "mandatory",
        validateResource: [
            validateResourceOfType(aws.iam.Policy, (p, _args, v) => report(wildcardActions(p.policy), v)),
            validateResourceOfType(aws.iam.RolePolicy, (p, _args, v) => report(wildcardActions(p.policy), v)),
            validateResourceOfType(aws.iam.Role, (r, _args, v) => {
                for (const inline of r.inlinePolicies ?? []) report(wildcardActions(inline.policy), v);
            }),
        ],
    },
    {
        name: "aurora-deletion-protection",
        description: "Aurora / RDS clusters must have deletion protection on.",
        enforcementLevel: "mandatory",
        validateResource: validateResourceOfType(aws.rds.Cluster, (c, _args, v) => {
            if (c.deletionProtection !== true) v("Set deletionProtection: true on every prod cluster.");
        }),
    },
    {
        name: "claim-buckets-block-public-access",
        description: "Every public access block must set all four flags to true.",
        enforcementLevel: "mandatory",
        validateResource: validateResourceOfType(aws.s3.BucketPublicAccessBlock, (b, _args, v) => {
            const flags = {
                blockPublicAcls: b.blockPublicAcls,
                blockPublicPolicy: b.blockPublicPolicy,
                ignorePublicAcls: b.ignorePublicAcls,
                restrictPublicBuckets: b.restrictPublicBuckets,
            };
            const off = Object.entries(flags).filter(([, val]) => val !== true).map(([k]) => k);
            if (off.length > 0) v(`Public access block must set ${off.join(", ")} to true.`);
        }),
    },
];
EOF
cat > index.ts <<'EOF'
// Entry point of the policy pack. Constructing PolicyPack starts the policy analyzer when the
// Pulumi CLI runs it (`pulumi up --policy-pack <dir>`); the checks live in policies.ts.
import { PolicyPack } from "@pulumi/policy";
import { policies } from "./policies";

new PolicyPack("example-org-aws-policies", { policies });
EOF
cat > policies.test.ts <<'EOF'
// Calls each check with hand-made resource properties, without the Pulumi engine or any cloud.
// Proves the checks' logic; does NOT prove how the Pulumi CLI wires them in (type tokens, unknown
// values during preview). Run: npm test.
import * as assert from "node:assert/strict";
import { policies } from "./policies";

type Validation = (args: { type: string; props: Record<string, unknown> }, report: (m: string) => void) => void;

function violations(policyName: string, type: string, props: Record<string, unknown>): string[] {
    const policy = policies.find((p) => p.name === policyName)!;
    const checks = ([] as unknown[]).concat(policy.validateResource) as Validation[];
    const found: string[] = [];
    for (const check of checks) check({ type, props }, (m) => found.push(m));
    return found;
}

const cases: Array<[string, string, Record<string, unknown>, boolean]> = [
    // [policy, Pulumi type token, props, expect a violation]
    ["iam-no-wildcard-actions", "aws:iam/policy:Policy",
        { policy: JSON.stringify({ Statement: [{ Effect: "Allow", Action: "*", Resource: "*" }] }) }, true],
    ["iam-no-wildcard-actions", "aws:iam/rolePolicy:RolePolicy",
        { policy: { Statement: [{ Effect: "Allow", Action: ["s3:*"], Resource: "*" }] } }, true],
    ["iam-no-wildcard-actions", "aws:iam/role:Role",
        { inlinePolicies: [{ name: "x", policy: JSON.stringify({ Statement: { Effect: "Allow", NotAction: "iam:*", Resource: "*" } }) }] }, true],
    ["iam-no-wildcard-actions", "aws:iam/policy:Policy",
        { policy: JSON.stringify({ Statement: [{ Effect: "Allow", Action: ["s3:GetObject"], Resource: "arn:aws:s3:::b/*" }] }) }, false],
    ["iam-no-wildcard-actions", "aws:iam/policy:Policy",
        { policy: JSON.stringify({ Statement: [{ Effect: "Deny", Action: "*", Resource: "*" }] }) }, false],
    ["aurora-deletion-protection", "aws:rds/cluster:Cluster", { deletionProtection: false }, true],
    ["aurora-deletion-protection", "aws:rds/cluster:Cluster", {}, true],
    ["aurora-deletion-protection", "aws:rds/cluster:Cluster", { deletionProtection: true }, false],
    ["claim-buckets-block-public-access", "aws:s3/bucketPublicAccessBlock:BucketPublicAccessBlock",
        { blockPublicAcls: true, blockPublicPolicy: true, ignorePublicAcls: true, restrictPublicBuckets: false }, true],
    ["claim-buckets-block-public-access", "aws:s3/bucketPublicAccessBlock:BucketPublicAccessBlock",
        { blockPublicAcls: true, blockPublicPolicy: true, ignorePublicAcls: true, restrictPublicBuckets: true }, false],
    // a check must ignore other resource types
    ["aurora-deletion-protection", "aws:s3/bucket:Bucket", { deletionProtection: false }, false],
];

let failed = 0;
for (const [name, type, props, expected] of cases) {
    const got = violations(name, type, props).length > 0;
    try {
        assert.equal(got, expected);
        console.log(`ok   ${name} ${type} -> ${expected ? "violation" : "pass"}`);
    } catch {
        failed++;
        console.log(`FAIL ${name} ${type}: expected ${expected ? "violation" : "pass"}`);
    }
}
for (const p of policies) assert.equal(p.enforcementLevel, "mandatory", p.name);
console.log(`${cases.length - failed}/${cases.length} cases passed; all policies mandatory`);
process.exit(failed ? 1 : 0);
EOF
